window.SEARCH_INDEX = [{"t": "Alan pas riche", "u": "index.html", "k": "Page", "a": "", "x": "Campagne D&D menée par Thibault. Notes de Mathieu, joueur de Morrÿs . 🗺️ Quêtes en cours Nom statut donneur lieu Le Gardien Bouclier active Wakanga O'Tamu Chult Le mal des ressuscités active Syndra Chult 📜 Dernières séances Nom date resume Séance 06 — Les guides de Port Nyanzaru 22/09/2026 Le groupe traverse Port Nyanzaru jusqu'à la maison de repos de Kaya, écoute les rumeurs sur les morts qu'on ne ramène plus et découvre les guides de la jungle, tous à 5 po par jour. Séance 05 — Port Nyanzaru 15/09/2026 Après vingt jours de mer et d'étranges cauchemars, le groupe arrive à Port Nyanzaru où Wakanga O'Tamu lui demande d'abord de sauver Syndra, frappée par le mal qui ronge les ressuscités. Séance 04 — L'Effleureuse 08/09/2026 Le groupe embarque à Leilon sur l'Effleureuse de Corvis Quillfore, échappe à un contrôle de la garde de Waterdeep et la sème grâce au pouvoir magique du navire. Séance 03 — Les Faiseurs de Veuves 01/09/2026 Au QG des Faiseurs de Veuves, Yarno El Raïb met le groupe à l'épreuve contre Lyra puis l'envoie à Chult chercher le Gardien Bouclier de Wakanga O'Tamu, avec Destos. Séance 02 — La route de Phandalin 25/08/2026 Les évadés quittent Waterdeep avec le capitaine Virgile, font profil bas dans une taverne en route et sont attendus aux portes de Phandalin par une elfe des Faiseurs de Veuves. 👤 PNJ récents Nom statut role lieu derniere apparition Kaya allié Aubergiste Maison de repos de Kaya Séance 06 Le domestique de Wakanga allié Domestique Villa de Wakanga O'Tamu Séance 06 River Mist et Flask of Wine inconnu Guides non officiels (supposé) Port Nyanzaru Séance 06 Arlan inconnu Frère de Corvis, marin Leilon Séance 05 Corvis Quillfore allié Capitaine de l'Effleureuse L'Effleureuse Séance 05 La Paire inconnu Vigies des Faiseurs de Veuves à Chult Port Nyanzaru Séance 05 Syndra allié Ancienne aventurière Villa de Wakanga O'Tamu Séance 05 Wakanga O'Tamu allié Prince marchand, mage Villa de Wakanga O'Tamu Séance 05 Alan allié Tavernier QG des Faiseurs de Veuves Séance 04 Le capitaine de la BITE hostile Capitaine d'un navire de la garde de Waterdeep Waterdeep Séance 04 ✏️ Fiches à créer Liens vers des fiches qui n'existent pas encore : Aucun lien cassé 🎉"}, {"t": "Chronologie", "u": "chronologie.html", "k": "Page", "a": "", "x": "Frise des événements, séance par séance. Dates réelles (et date dans le monde quand elle est connue). Séance 01 — La Faille de Waterdeep (2026-07-15) Réveil en cellule à la Prison de Waterdeep , évasion pendant une invasion de kobolds, rencontre d' Alan . Combat aux côtés du capitaine ( Virgile ), qui laisse partir le groupe. Une créature invisible l'abat ; un halfelin ( Corrin Thinspike ) la tue et conseille Phandalin . Séance 02 — La route de Phandalin (2026-08-25 · mai) Départ de Waterdeep avec Virgile et Alan , deux jours de marche. Halte dans une taverne, profil bas en guenilles de prisonniers. Arrivée aux abords de Phandalin : fumée, Lyra Sunstrike attend le groupe devant la villa des Faiseurs de Veuves . Séance 03 — Les Faiseurs de Veuves (2026-09-01 · mai) Entrée au QG des Faiseurs de Veuves , rencontre de Yarno El Raïb et Destos . Épreuve contre Lyra Sunstrike réussie ; mission du Gardien Bouclier à Chult acceptée. Alan reste aux cuisines, Virgile repart à Waterdeep . Séance 04 — L'Effleureuse (2026-09-08) Départ de Phandalin avec Lyra Sunstrike , embarquement à Leilon sur L'Effleureuse de Corvis Quillfore . Contrôle par la Brigade d'Intervention Technique et Expéditive ; fuite, la garde s'échoue. Séance 05 — Port Nyanzaru (2026-09-15) Vingt jours de traversée ; cauchemars de tout le groupe dès la première nuit. Arrivée à Port Nyanzaru au milieu d'une procession funèbre. À la Villa de Wakanga O'Tamu , Syndra expose Le mal des ressuscités ; rumeur du Soulmonger . La Paire est sans nouvelles depuis ~20 jours ; quelqu'un observe le groupe. Séance 06 — Les guides de Port Nyanzaru (2026-09-22) Traversée de Port Nyanzaru ( Temple de Gond , marchés) jusqu'à la Maison de repos de Kaya . Rumeurs sur les morts qu'on ne ramène plus ; conseils de Kaya . Tarifs et prospectus de la Guilde des guides ; rumeurs sur l' Enclave d'Émeraude et le Zhentarim ."}, {"t": "Questions ouvertes", "u": "questions-ouvertes.html", "k": "Page", "a": "", "x": "Mystères, zones d'ombre et points à éclaircir. Cocher quand c'est résolu, en indiquant la séance. Prison de Waterdeep Comment Kael, Morrÿs et Obélik se sont-ils retrouvés en prison ? ( Séance 01 ) D'où vient la faille de la Prison de Waterdeep , et pourquoi l'invasion de kobolds ? ( Séance 01 ) Qui a envoyé La créature invisible , et pour qui ? ( Séance 01 ) Qui était la petite voix dans leur tête qui a proposé le plan de l'appât ? ( Séance 01 ) Groupe et guilde Comment Lyra Sunstrike savait-elle que le groupe arrivait à Phandalin ? ( Séance 02 ) — Corrin Thinspike avait prévenu la guilde ( Séance 03 ) La villa à l'étoile à huit branches est-elle le QG des Faiseurs de Veuves ? ( Séance 02 ) — oui ( Séance 03 ) Personnages Le halfelin a cru reconnaître Alan , qui dit ne pas le connaître : lien avec sa ressemblance au fils de Neverember ? ( Séance 02 ) Comment Virgile connaît-il les Faiseurs de Veuves ? ( Séance 02 ) Quel fondateur des Faiseurs de Veuves a envoyé Yarno El Raïb en prison, et pourquoi ? ( Séance 03 ) Quels sont les pouvoirs de Lyra Sunstrike (elle vide l'énergie de ses cibles à mains nues) ? ( Séance 03 ) La guilde a une trentaine d'années, mais sa réputation « une vingtaine » (notes de séance 02) : simple nuance ou erreur ? ( Séance 03 ) Voyage La garde sait-elle que le groupe va à Chult (Destos l'a laissé échapper) ? ( Séance 04 ) Qu'est-ce que le petit objet bleu qui active le pouvoir de L'Effleureuse ? ( Séance 04 ) Chult D'où viennent les cauchemars de la traversée, tous marqués par la même obscurité ? ( Séance 05 ) Qui observe le groupe à Port Nyanzaru ? ( Séance 05 ) Où est La Paire , et quelle était sa mission ? ( Séance 05 ) Le Soulmonger existe-t-il, et est-il la cause du mal des ressuscités ? ( Séance 05 ) Qu'est devenu le dernier groupe parti pour Syndra ? ( Séance 05 ) Quel guide engager ? Les accusations de Salida contre les autres guides sont-elles vraies ? ( Séance 06 ) Qui est Malar's Throat, sur le panneau des guides sans prospectus ? ( Séance 06 ) — un quartier de Port Nyanzaru, titre d'une annonce non officielle (transcription de la Séance 06 ) Qui sont River Mist et Flask of Wine , et que valent-ils ? ( Séance 06 ) Qui a-t-on enterré lors des trois processions funèbres de la semaine ? ( Séance 06 ) Quelle faction est liée aux zombies de Chult (Kaya en a parlé, nom non retenu) ? ( Séance 06 )"}, {"t": "Séance 01 — La Faille de Waterdeep", "u": "seances/seance-01.html", "k": "📜 Séances", "a": "", "x": "Résumé rapide La dernière fois, Kael , Morrÿs et Obélik se sont réveillés dans une cellule de la Prison de Waterdeep , sans savoir pourquoi. Profitant d'une invasion de kobolds, on s'est évadés avec Alan , un tavernier. On a vu une faille sans fond, une fosse commune, et on a gravi un escalier-toboggan à la corde et aux pitons, sans jamais utiliser le code trouvé sur un garde. Dans le hall, on a aidé le capitaine de la prison contre les kobolds ; il a décidé de nous laisser partir. Dehors, une créature invisible l'a transpercé. Morrÿs a servi d'appât, et un vieux halfelin l'a abattue d'une flèche : « Sale bête. » Il a soigné le capitaine, a semblé reconnaître Alan, nous a conseillé de fuir vers Phandalin , puis est reparti dans la prison en marchant au plafond. Résumé Séance d'initiation. Kael , Morrÿs et Obélik se réveillent dans une cellule de la Prison de Waterdeep sans savoir comment ils y sont arrivés ; chacun estime y avoir été jeté à tort. Ils sortent de la cellule et profitent du chaos : des kobolds ont envahi la prison. Dans une salle des gardes servant de stockage d'armes, ils rencontrent Alan , un tavernier de Waterdeep lui aussi évadé. Une immense faille dont on ne voit pas le fond s'ouvre dans la salle. Plus loin, une fosse commune remplie de cadavres (« ça sent la chèvre en décomposition », selon Kael). Pour atteindre le hall, il faut gravir un escalier magique de 50 à 100 marches qui se change en toboggan et déclenche une alarme dès qu'on s'y engage. Le groupe a trouvé un code sur le cadavre d'un garde au pied de l'escalier… mais ne s'en sert pas : il monte à la corde et aux pitons, marche après marche. Dans le hall, le capitaine de la garde ( Virgile , nom appris à la séance suivante) combat seul une horde de kobolds, dont certains ailés ; le groupe l'aide à en finir. Il comprend vite qu'il a affaire à des évadés (un bluff échoue), mais la prison n'étant plus sûre, il décide de les laisser partir. Dehors, une créature invisible le transperce d'une épée. Le groupe le soigne, elle frappe à nouveau et il s'effondre ; les évadés se réfugient dans le hall. Une petite voix dans leur tête propose un plan : Morrÿs ressort servir d'appât. La créature apparaît une fraction de seconde, épée levée… et une flèche la tue net. Le tireur est un halfelin d'une soixantaine d'années ( Corrin Thinspike , nom appris en Séance 03 ) : « Sale bête. » Il soigne le capitaine, semble reconnaître Alan — qui nie le connaître — et juge anormale la présence d'une créature aussi puissante ici. Il conseille au groupe de quitter Waterdeep pour Phandalin , puis retourne dans la prison, les mains dans les poches, en marchant sur les murs puis au plafond, pour « faire un peu de ménage ». Chronologie Réveil en cellule, évasion. Rencontre d' Alan dans la salle des gardes ; la faille. Fosse commune. Escalier-toboggan gravi à la corde et aux pitons (code du garde inutilisé). Combat contre les kobolds aux côtés du capitaine. Le capitaine laisse partir le groupe ; attaque de la créature invisible. Morrÿs sert d'appât ; le halfelin tue la créature, soigne le capitaine, conseille Phandalin . PNJ rencontrés Alan : tavernier évadé, rejoint le groupe. Virgile : capitaine de la garde de la prison, laisse partir le groupe. Corrin Thinspike : halfelin mystérieux, tue la créature invisible. La créature invisible : attaque le capitaine, tuée d'une flèche. Quêtes Rejoindre Phandalin : nouvelle (conseil du halfelin). Butin et récompenses Un code trouvé sur un garde mort (non utilisé). Citations et moments marquants « Sale bête. » — le halfelin, après avoir tué la créature invisible Kael : la fosse commune « sent la chèvre en décomposition ». L'ascension de l'escalier-toboggan, piton après piton, sans jamais utiliser le code. Questions ouvertes Comment le groupe est-il arrivé en prison ? D'où vient la faille, et pourquoi des kobolds envahissent-ils la prison ? Qui était la petite voix dans leur tête ? Qui a envoyé la créature invisible, et pourquoi ? Sources Récit d"}, {"t": "Séance 02 — La route de Phandalin", "u": "seances/seance-02.html", "k": "📜 Séances", "a": "", "x": "Résumé rapide La dernière fois, on a quitté Waterdeep pour Phandalin avec Alan et le capitaine blessé, qui s'appelle Virgile . Il avait jeté une chope, vidée avant, dans la faille de la prison. Halte de nuit dans une taverne : en guenilles de prisonniers, on a fait profil bas, mais les clients chuchotaient. Alan nous a raconté qu'il gère une taverne qu'il rêve de racheter, qu'il a été arrêté pour des affiches publicitaires, et qu'on le confond souvent avec le fils de Neverember , l'ancien lord de Waterdeep. Virgile veut se faire soigner par les Faiseurs de Veuves , une guilde qui œuvre pour le bien malgré son nom. En arrivant, fumée au-dessus de la ville ; devant une villa marquée d'une étoile à huit branches, une elfe de la guilde nous attendait depuis plusieurs jours, sans qu'on ait prévenu personne. Résumé Sortis de la Prison de Waterdeep , Kael , Morrÿs , Obélik et Alan prennent la route de Phandalin , à deux jours de marche. Le capitaine de la prison, blessé mais soigné par le halfelin mystérieux (reparti explorer la prison), les accompagne ; il se présente enfin : Virgile . Il n'est affecté à la garde de la prison que depuis l'an dernier. Il raconte avoir tenté de sonder la faille de la prison en y jetant une chope — vidée au préalable, on ne gâche pas — ce qui scandalise surtout Alan (le trou est très profond : « 10 secondes »). Virgile décide de s'arrêter pour la nuit dans une taverne sur la route. Les évadés, toujours en guenilles de prisonniers, doivent faire profil bas pendant qu'il commande pour tout le monde en précisant au tavernier qu'ils sont avec lui. Morrÿs entend des chuchotements : les clients les ont repérés, mais personne ne pose de question. À table, Alan se raconte : il est gérant d'une taverne à Waterdeep qu'il voudrait un jour racheter, et il a été emprisonné pour « propagande » (des affiches publicitaires pour sa taverne). À Waterdeep, on le confond souvent avec le fils de Neverember , le lord de la cité avant Jeanne Von Brocht . Virgile, lui, compte se faire soigner à Phandalin par les Faiseurs de Veuves , une guilde qui y a son QG et œuvre pour le bien du royaume. Elle a cette réputation depuis une vingtaine d'années ; son nom vient de sa toute première mission, où elle n'a pas réussi à sauver tous les otages. On est au mois de mai. Le groupe reprend la route ; à l'approche de Phandalin, une colonne de fumée s'élève au-dessus de la ville (Obélik : « Ils ont déjà allumé le barbecue »). Devant une vaste villa à l'extérieur de la ville, marquée d'une étoile à huit branches — le symbole des Faiseurs de Veuves — une elfe de la guilde, Lyra Sunstrike , les attend depuis quatre ou cinq jours, alors que personne n'a annoncé leur venue. Chronologie Départ de Waterdeep vers Phandalin (deux jours de marche) avec Virgile . Virgile raconte la chope jetée dans la faille de la Prison de Waterdeep . Halte de nuit dans une taverne sur la route : profil bas, chuchotements des clients. Confidences d' Alan (taverne, affiches, ressemblance avec le fils de Neverember ). Virgile présente les Faiseurs de Veuves . Reprise de la route ; fumée au-dessus de Phandalin. Une elfe des Faiseurs de Veuves ( Lyra Sunstrike ) les attend devant la villa à l'étoile à huit branches. PNJ rencontrés Virgile : capitaine de la prison, blessé, voyage avec le groupe pour se faire soigner. Alan : tavernier évadé avec le groupe. Lyra Sunstrike : elfe des Faiseurs de Veuves qui attend le groupe (nom appris plus tard). Corrin Thinspike : évoqué — le halfelin qui a soigné Virgile et est reparti vers la prison. Neverember , Jeanne Von Brocht : évoqués (ancien et actuel lord de Waterdeep). Quêtes Rejoindre Phandalin : avancée (arrivée aux abords de la ville). Butin et récompenses Rien. Citations et moments marquants « Ils ont déjà allumé le barbecue. » — Obélik, devant la fumée de Phandalin La chope jetée dans la faille… mais vidée avant. Questions ouvertes Comment l'elfe savait-elle que le groupe arrivait ? Sources Notes de Mathieu (inbox, 2026-09-"}, {"t": "Séance 03 — Les Faiseurs de Veuves", "u": "seances/seance-03.html", "k": "📜 Séances", "a": "", "x": "Résumé rapide La dernière fois, au QG des Faiseurs de Veuves , l'elfe, Lyra , nous a présentés à Yarno El Raïb . Le halfelin de la prison, Corrin Thinspike , nous avait recommandés. La guilde neutralise les objets magiques dangereux et veut faire tomber la lord Jeanne Von Brocht . Comme on ne peut rester ni à Waterdeep ni à Phandalin, Yarno nous envoie à Chult : le prince marchand Wakanga O'Tamu cherche un Gardien Bouclier et son amulette. Nos contacts sur place : les sœurs Vesper, La Paire . On a passé l'épreuve contre Lyra, et le poignard de Morrÿs a fini au plafond. On a reçu 50 po, une potion de soin et une antipoison chacun. Destos , un clerc, part avec nous. Alan reste aux cuisines ; Virgile rentre à Waterdeep. Départ à l'aube. Résumé L'elfe fait entrer le groupe dans la vaste demeure hors de Phandalin : c'est le QG des Faiseurs de Veuves . Près de la porte, Morrÿs et Obélik reconnaissent l'étoile à huit branches, emblème de la guilde. Dans le patio, elle appelle Yarno El Raïb et le groupe apprend enfin son nom : Lyra . Yarno discute avec un homme chauve, Destos . Il sait déjà qui ils sont : le halfelin de la prison, Corrin Thinspike , l'a prévenu et les a recommandés. Le groupe raconte son arrestation et son évasion ; l'évocation de « l'autre connasse » ( Jeanne Von Brocht ) fait rire Yarno : elle arrête les gens à tour de bras et la guilde réunit des preuves pour la faire tomber. Impossible de retourner à Waterdeep , et rester à Phandalin attirerait des ennuis à la guilde : il faut partir. Yarno explique le vrai rôle des Faiseurs de Veuves : retrouver les objets magiques dangereux, les neutraliser, voire les détruire. Il propose une mission à Chult : le prince marchand Wakanga O'Tamu cherche un Gardien Bouclier et l'amulette qui le contrôle. Contacts sur place : Iolka et Nera Vesper , « la Paire », vigies de la guilde qui logent chez Wakanga. À Chult, le groupe agira en son nom propre, pas au nom de la guilde : trésors abandonnés autorisés, vol interdit. Épreuve au sous-sol : toucher trois fois Lyra, qui se bat à mains nues et vide l'énergie de ses cibles d'un coup de paume. Obélik, Destos puis Kael sont touchés, Obélik et Kael finissent au sol. Obélik la touche puis l'immobilise, Destos l'atteint d'un sort : objectif rempli. Le poignard de Morrÿs, lancé deux fois, est dévié dans un mur puis planté dans le plafond (« l'inconvénient des armes de jet », dixit Yarno) ; Obélik saute pour le récupérer. Chambres à l'étage, avec terrasse plein sud : au loin, la montagne où ils étaient emprisonnés. Au jardin, quatre statues des fondateurs de la guilde, née à Phandalin il y a une trentaine d'années ; Yarno a été envoyé en prison, il y a des années, par l'un d'eux. Chacun reçoit 50 po, une potion de soin et une potion antipoison ; Yarno remettra une carte de Chult et une photo de la Paire. Départ à l'aube, 21 jours de mer (jusqu'à 40 si le temps est mauvais) ; Destos est du voyage. Alan prend une place dans les cuisines du QG. Virgile retourne à Waterdeep pour ne pas passer pour déserteur (version officielle : les prisonniers se sont joués de lui) ; Lyra et Destos le soignent dans le patio. Alan cuisine un chevreuil en sauce ; Morrÿs demande du chocolat (Alan ne connaît pas) : le groupe promet de lui rapporter des épices de Chult. Au dîner dans le Salon Bleu, Yarno parle des sept Princes marchands qui gouvernent Port Nyanzaru et conseille à Destos, homme du Nord, d'alléger sa tenue. Chronologie Entrée au QG, rencontre de Yarno El Raïb et Destos ; le nom de Lyra. Recommandation de Corrin Thinspike ; Jeanne Von Brocht visée par la guilde. Proposition de la mission du Gardien Bouclier à Chult . Épreuve contre Lyra Sunstrike : réussie. Chambres, jardin des quatre fondateurs, remise de l'équipement. Alan aux cuisines, Virgile repart vers Waterdeep. Dîner au Salon Bleu ; départ prévu à l'aube. PNJ rencontrés Lyra Sunstrike : fait passer l'épreuve, soigne Virgile. Yarno El Raïb : membre de la guilde, confie la mission. Alan : entre aux"}, {"t": "Séance 04 — L'Effleureuse", "u": "seances/seance-04.html", "k": "📜 Séances", "a": "", "x": "Résumé rapide La dernière fois, Lyra nous a menés à Leilon , où nous attendait L'Effleureuse , le trois-mâts magique de Corvis Quillfore . Sans équipage, on a dû faire les manœuvres nous-mêmes. Dès le départ, un navire de la garde de Waterdeep, la BITE , nous a contrôlés. Obélik s'est appelé « Hervé », Destos a laissé échapper le mot « Chult », et Morrÿs, reconnu sur l'avis de recherche, a été ligoté. Obélik a tranché la corde entre les navires, Kael a jeté le capitaine adverse à l'eau, et on a fui sous les carreaux. Corvis a activé le pouvoir du navire avec un petit objet bleu : on a bondi par-dessus des hauts-fonds, et la garde s'y est échouée. Corvis, tombé à l'eau, a été réveillé d'une gifle par Obélik. Cap sur Chult. Résumé Avant l'aube, Lyra vient chercher Kael , Morrÿs , Obélik et Destos ; Alan et Virgile les regardent partir. Le récit parle d'une matinée fraîche « malgré le mois de juillet ». Lyra porte désormais une cape sombre et un masque pâle lié à sa discipline monacale. Elle aurait aimé venir (Chult est « the place to be »), mais la guilde veut rester discrète. Sur les deux heures de route vers Leilon , chacun raconte d'où lui vient son aptitude au combat : Kael a appris auprès des membres de la caravane itinérante où il a vécu ; Destos se dit « vaisseau de la lumière », parti de son village pour la répandre ; Obélik était fermier ; Morrÿs a appris à lancer des couteaux… la veille. À Leilon attend L'Effleureuse , trois-mâts fin comme un oiseau, commandée par Corvis Quillfore , qui compte faire la traversée en vingt jours plutôt que quarante. Morrÿs sent qu'une magie habite le navire. Prévenu la veille, Corvis n'a pas d'équipage : Obélik aux cordages, Morrÿs à la navigation avec Corvis, Kael à la vigie, Destos « tout le reste » (lignes de vie, bouts, canon). Corvis déposera le groupe à Chult avant de repartir vers les îles Solaires. Dès le départ, un navire de la garde de Waterdeep les intercepte : la Brigade d'Intervention Technique et Expéditive (la « BITE ») veut inspecter la cargaison. Corvis gagne du temps, les fugitifs se changent. Le capitaine de la BITE monte avec quatre soldats ; Corvis prétend livrer du minerai aux îles Solaires. Obélik se présente comme « Hervé » (aidé d'un sort de Destos) ; Destos dit vouloir gagner Chult et laisse échapper le nom ; Kael explique sa peau bleue par une maladie et fait mine de vomir. Le capitaine a un avis de recherche avec quatre portraits : Kael, Obélik, Morrÿs et Alan — Morrÿs se ressemble beaucoup. Obélik fait parler le capitaine (ancien marin de l'import-export, licence perdue) et manque de lui proposer de rejoindre l'équipage. Destos provoque un phénomène par thaumaturgie sur le navire de la garde : le capitaine y retourne (il appelle Rico et Muso), laissant un soldat ligoter Morrÿs, qui a le temps de répandre ses billes. Obélik tranche la corde qui relie les navires. Il expédie le dernier soldat sur son bâtiment, Kael jette le capitaine adverse par-dessus bord, un soldat rate son saut et tombe aussi à l'eau. Morrÿs, ligoté, se plante son propre poignard dans le bras. Poursuite : Obélik prend un carreau d'arbalète dans la jambe, un tonneau est percé. Destos simule sous la coque ennemie le grondement d'une créature (ça marche une fois). Kael signale des hauts-fonds ; Corvis garde le cap, sort un petit objet bleu lumineux, le vent forcit et l'Effleureuse bondit par-dessus. Destos tombe dans la cale, Corvis passe par-dessus bord, retenu par sa ligne de vie ; Obélik le remonte. Le navire de la garde s'échoue sur le banc de sable. Corvis, inconscient, résiste aux soins de Kael et Morrÿs ; une gifle d'Obélik le réveille. Le pouvoir du navire ne peut pas servir à volonté. Destos cherche un traqueur par détection de la magie : tout le navire rayonne, rien de distinct. Kael trouve une marmite du ragoût de chevreuil d'Alan : c'est le frère de Corvis qui l'a cuisiné. Morrÿs demande de la mousse au chocolat ; Corvis ne connaît pas. Chronologie Départ de Phandalin avant l'aube "}, {"t": "Séance 05 — Port Nyanzaru", "u": "seances/seance-05.html", "k": "📜 Séances", "a": "", "x": "Résumé rapide La dernière fois, pendant les vingt jours de traversée, on a tous fait des cauchemars de notre passé envahis par la même obscurité. On est arrivés à Port Nyanzaru en pleine procession funèbre. Un domestique nous a conduits chez Wakanga O'Tamu , qui nous a présenté Syndra , une vieille elfe autrefois ressuscitée. Tous les ressuscités dépérissent, et plus personne ne peut ramener les morts. La source serait dans la jungle, au sud, peut-être le Soulmonger , un artefact qui capturerait les âmes. On a accepté d'aider Syndra en priorité, avant le Gardien Bouclier. Wakanga nous a donné une carte de Chult et la piste du journal d'une naine. Il nous a conseillé de prendre un guide et de nous équiper, et nous loge chez Kaya. La Paire ne donne plus de nouvelles depuis vingt jours. En sortant, Kael a senti qu'on nous observait. Résumé Pendant la traversée, le groupe découvre L'Effleureuse (cabine du capitaine, deux cabines doubles, mess, cale, quelques canons inutilisés). Corvis Quillfore explique qu'il a manqué d'équipage parce que son frère Arlan était parti avec un autre navire. Il raconte Leilon : ancien port de pêche qui a grandi quand les Faiseurs de Veuves y ont rallumé la forge magique ; Corvis et Arlan, pêcheurs à l'origine, y ont monté leur compagnie de transport. Il ne connaît pas Chult . Leçon de pêche ; Morrÿs révèle qu'il respire sous l'eau, d'où un projet (non exécuté) de ski nautique. Quarts de nuit, ligne de vie obligatoire sur le pont. Une ombre s'étend sur les rêves : Morrÿs revoit une part de son passé déformée par une obscurité oppressante ; Obélik un événement qu'il voulait oublier, assombri ; Kael la caravane de son enfance engagée dans un tunnel sans fin ; Destos le temple qu'il a quitté, qui se flétrit. Pendant son quart, Morrÿs se déguise en « vrai » capitaine. Obélik ronfle, prétend ne pas dormir, et vomit par-dessus bord. Vers le quinzième jour, la chaleur monte, l'eau devient turquoise ; Obélik prend des tortues marines pour un dragon des mers. Pas de pêche à la tortue (une divinité tortue existe peut-être) ; Corvis en a mangé une fois, échoué sur une île. Après vingt jours, arrivée à Port Nyanzaru par le nord : digue, chaîne, phare, fort. Chaleur, épices, et une procession funèbre silencieuse (porteurs en blanc couverts de cendre, bannières noires, fleurs blanches, étals fermés). Corvis indique les auberges près du bazar (est) et le quartier marchand (ouest), puis part recruter un équipage. Un domestique à éventail aborde le groupe : « les voyageurs envoyés par la guilde ? » — Obélik répond oui avant qu'on lui rappelle la consigne. À la Villa de Wakanga O'Tamu , dans un quartier aux fresques de dinosaures, Wakanga O'Tamu confirme la mission du Gardien Bouclier mais présente d'abord Syndra , très vieille elfe masquée de dentelle. Ancienne aventurière tuée dans une embuscade puis ressuscitée, elle dépérit : toutes les personnes ramenées à la vie souffrent du même mal, et les prêtres ne parviennent plus à ressusciter personne. La source serait dans la jungle, sans doute loin au sud ; d'autres groupes sont partis, aucun n'est revenu (le dernier il y a une vingtaine de jours). Syndra soupçonne un artefact plutôt que les dieux ; Wakanga évoque la rumeur du Soulmonger , qui capturerait les âmes des défunts — à étudier, sinon à détruire. Le groupe accepte : sauver Syndra passe avant le construct. Wakanga conseille de s'informer, de s'équiper et d'engager un guide avant de partir. Il détaille les sept Princes marchands , la justice locale (esclavage interdit, ordres d'assassinat légaux et payants, « course contre la mort » face à des dinosaures) et les courses de dinosaures (une a lieu dans deux jours ; dernier accident mortel il y a deux mois). Il remet une carte de Chult ; le journal d'une naine situe le Gardien Bouclier à l'intérieur des terres, peut-être en suivant la rivière. La Paire n'a pas donné de nouvelles depuis une vingtaine de jours, partie sur une autre mission. Wakanga paie leur séjour à l"}, {"t": "Séance 06 — Les guides de Port Nyanzaru", "u": "seances/seance-06.html", "k": "📜 Séances", "a": "", "x": "Résumé rapide La dernière fois, on a traversé Port Nyanzaru jusqu'à l'auberge de Kaya , payée par Wakanga. Destos garde la carte de la ville, et Obélik le journal de la naine dans une bourse à son pagne. Rumeur à l'auberge : c'est déjà la troisième procession de la semaine. Kaya nous a prévenus que dehors on est des proies. Il faut suivre la rivière Soshenstar pour ne pas se perdre, et surtout prendre un guide, car tous ceux qui sont revenus en avaient un. Il y a des zombies sur l'île. Sur le panneau de l'auberge, on a trouvé six guides officiels et une annonce louche, signée River Mist et Flask of Wine. Le domestique de Wakanga nous a donné leurs prospectus. Tarif unique : 5 po par jour, 30 jours d'avance, et on n'a que 200 po. Il nous reste à choisir un guide. Résumé Traversée de la ville Même journée que la Séance 05 : arrivé au port en début de matinée, le groupe ressort de la Villa de Wakanga O'Tamu moins d'une heure plus tard. Il décide d'aller d'abord repérer l'auberge de Kaya, en ouvrant l'œil pour trouver du chocolat (Morrÿs). Petit Temple de Gond dans le quartier marchand. Destos sait que Gond est le dieu des portes, au propre comme au figuré (opportunités, destin), vénéré par les artisans (symbole de forge). La ville avance à deux vitesses : quartiers silencieux en deuil d'un côté, foule très colorée qui parle un créole à claquements de gorge et de dents de l'autre (du beatbox, pour Morrÿs). Un palais doré domine la ville depuis sa colline ; au loin, le grand colisée. Sur l'idée de Destos, le groupe répartit ce qu'il ne veut pas se faire voler : Destos garde la carte de la ville dans sa robe, Obélik le Journal de la naine dans une bourse accrochée à son pagne. Un passant (« encore des touristes ») renseigne Kael : le grand bazar à trois branches est ouvert tous les jours du matin au soir ; l'auberge de Kaya est à l'est, près du bazar rouge. En chemin, un second marché plus quotidien (viande de dinosaure, fruits, légumes, vêtements) et une autre auberge, le Lézard tonnant . Chez Kaya À la Maison de repos de Kaya , Kaya , tenancière austère (« un sou est un sou »), attendait le groupe. Elle lui donne les deux chambres du fond, 40 et 42 (Kael partage la sienne avec Morrÿs), payées par Wakanga, repas du soir compris. Elle prévient : ne voler ni déranger personne, la justice locale est sévère. L'intuition de Kael la juge sincère et attachée à sa réputation. Obélik repère un panneau d'annonces à l'entrée. Au brunch (1 pa par personne), le groupe écoute les conversations voisines. Obélik et Kael entendent : « tout le monde devient fou avec ce truc », c'est la troisième procession de la semaine ; on ne sait pas ce qui se passe dans l'au-delà, mais c'est bizarre de dépenser autant sans en profiter. Kael règle les 4 pa avec une pièce d'or pour montrer que le groupe est solvable. On convient de dire à Kaya où l'on va, mais pas pourquoi (« c'est pour le prince »). Conseils de Kaya Port Nyanzaru est à peu près le seul endroit civilisé de l'île ; dehors, on est plutôt des proies. Beaucoup d'expéditions ont voulu cartographier et sécuriser l'île : peu sont revenues, aucune n'a réussi, même si des factions tentent d'y bâtir des places fortes. Le pire danger est de se perdre : suivre une rivière (la Soshenstar, vers le sud) donne un repère, en louant une pirogue ou un canoë. Attention aux bêtes dans l'eau. Prendre un guide : tous ceux qui sont revenus en avaient un. Les guides dépendent du prince marchand Jobal ( Guilde des guides ). Des zombies sur l'île, depuis toujours : on ne sait pas d'où ils viennent, ni s'ils ont un chef ; une faction est liée à l'affaire (nom non retenu). Les dinosaures n'attaquent que s'ils ont faim ou se sentent menacés. Au nord, le Fort Beluarian : une milice armée y maintient l'ordre et tient les zombies à l'écart. La ville, fortifiée et bien gardée, est plus sûre que n'importe quel fort. En partant en expédition, rendre les clés (elle en a marre de changer les serrures) ; si le groupe n'est pas revenu s"}, {"t": "Le Gardien Bouclier", "u": "quetes/le-gardien-bouclier.html", "k": "🗺️ Quêtes", "a": "Mission de Chult", "x": "Retrouver le Gardien Bouclier et son amulette de contrôle pour Wakanga O'Tamu , mission transmise par Yarno El Raïb des Faiseurs de Veuves . Le groupe agit en son nom propre. Avancement Séance 03 : Yarno propose la mission ; 50 po, potions, carte et photo de la Paire fournies ; départ à l'aube avec Destos. Séance 04 : traversée vers Chult sur l'Effleureuse ; la garde a peut-être entendu la destination. Séance 05 : Wakanga confirme la mission ; piste du journal d'une naine (intérieur des terres, suivre la rivière) ; passe après Syndra ; la Paire est injoignable. Séance 06 : préparatifs : Obélik garde le journal ; recherche d'un guide. Pistes et indices Contacter La Paire à Port Nyanzaru Suivre la piste du Journal de la naine (intérieur des terres, rivière) Engager un guide ( Guilde des guides , 5 po/jour, 30 jours d'avance) Personnes impliquées Wakanga O'Tamu Yarno El Raïb La Paire"}, {"t": "Le mal des ressuscités", "u": "quetes/le-mal-des-ressuscites.html", "k": "🗺️ Quêtes", "a": "Sauver Syndra", "x": "Trouver et arrêter la source du mal qui fait dépérir les ressuscités (dont Syndra ) et empêche toute nouvelle résurrection. Prioritaire sur Le Gardien Bouclier . Avancement Séance 05 : Syndra et Wakanga exposent le mal ; le groupe accepte et en fait sa priorité. Séance 06 : rumeurs à l'auberge (troisième procession) ; recherche d'un guide. Pistes et indices La source serait dans la jungle, sans doute loin au sud Rumeur du Soulmonger , qui capturerait les âmes Le dernier groupe parti enquêter (il y a ~20 jours) n'est pas revenu S'informer, s'équiper et engager un guide à Port Nyanzaru ( Guilde des guides ) Trois processions funèbres récentes : « tout le monde devient fou » Personnes impliquées Syndra Wakanga O'Tamu"}, {"t": "Rejoindre Phandalin", "u": "quetes/rejoindre-phandalin.html", "k": "🗺️ Quêtes", "a": "", "x": "Après l'évasion, le halfelin a conseillé au groupe de rejoindre Phandalin ; Virgile y va aussi pour se faire soigner par les Faiseurs de Veuves . Avancement Séance 01 : le halfelin conseille au groupe de fuir Waterdeep pour Phandalin. Séance 02 : deux jours de marche, halte dans une taverne ; arrivée aux abords de Phandalin, accueil par Lyra Sunstrike . Séance 03 : le groupe entre au QG des Faiseurs de Veuves. Pistes et indices Soigner Virgile auprès des Faiseurs de Veuves ( Séance 03 ) Personnes impliquées Virgile Alan"}, {"t": "Destos", "u": "personnages/destos.html", "k": "🛡️ Personnages", "a": "", "x": "Présentation Humain chauve venu du Nord, clerc. Rencontré au QG des Faiseurs de Veuves , il rejoint l'expédition à Chult . Se dit « vaisseau de la lumière » : il a quitté son village (et un temple) pour répandre la lumière dans le monde. Capacités notables Sorts de clerc (attaque à distance, soins, assistance, thaumaturgie, détection de la magie en rituel). Équipement notable La carte de Port Nyanzaru (depuis la Séance 06 ). Une tenue épaisse de nordique, trop chaude pour Chult. Historique Séance 03 : rencontré avec Yarno au QG ; atteint Lyra d'un sort pendant l'épreuve, soigne Virgile, rejoint l'expédition. Séance 04 : se dit « vaisseau de la lumière » ; laisse échapper le nom de Chult ; diversions par thaumaturgie ; cherche un traqueur. Séance 05 : premier quart ; cauchemar sur son temple ; se dit capable de repérer les maladies. Séance 06 : reconnaît le temple de Gond ; propose de répartir le matériel, garde la carte de la ville ; connaît l'Enclave d'Émeraude."}, {"t": "Kael", "u": "personnages/kael.html", "k": "🛡️ Personnages", "a": "", "x": "Présentation Orc rôdeur à la peau bleue, évadé de la Prison de Waterdeep avec Morrÿs et Obélik . A grandi dans une caravane itinérante où il a appris le combat, rencontre après rencontre. Vue perçante. Capacités notables Équipement notable Historique Séance 01 : se réveille en cellule, s'évade ; inspecte la fosse commune. Séance 02 : prend la route de Phandalin avec le groupe et Virgile . Séance 03 : passe l'épreuve à l'arc, finit au sol. Séance 04 : raconte sa jeunesse dans une caravane itinérante ; vigie ; jette le capitaine de la garde à l'eau. Séance 05 : cauchemar : sa caravane dans un tunnel sans fin ; sent qu'on les observe à Port Nyanzaru. Séance 06 : se renseigne auprès d'un passant ; partage sa chambre avec Morrÿs ; juge Kaya sincère et l'annonce de Malar's Throat racoleuse ; paie le brunch (4 pa)."}, {"t": "Morrÿs", "u": "personnages/morrys.html", "k": "🛡️ Personnages", "a": "Morrys", "x": "Nain artificier aux cheveux blancs, bricoleur de génie (ou presque) : ses sorts sont des machines « déréglées ». Évadé de la Prison de Waterdeep avec Kael et Obélik , envoyé à Chult par les Faiseurs de Veuves . Respire sous l'eau (bonnet). Profil (fiche de début de séance 5) CA 13 · PV 19 · Vitesse 9 m · Vision dans le noir 36 m · Résistance au poison Caractéristiques : FOR 10 · DEX 12 · CON 15 · INT 18 · SAG 9 · CHA 8 Langues : commun, nain, gnome Dons : Façonnage rapide, Ristourne Sorts : Réparation , Trait de feu (machine à popcorn déréglée), Rayon de givre (machine à sorbets déréglée), Soins (trousse de premiers secours), Graisse (lubrifiant industriel au lithium téflonné), Déguisement Équipement notable : bonnet de respiration aquatique, baguette des secrets, billes, outils de bricoleur, armure de cuir clouté, dague Jetons Fiches de personnage 📎 Fiche — fin de séance 4 📎 Fiche — début de séance 5 Historique Séance 01 : se réveille en cellule, s'évade ; sert d'appât à la créature invisible, sauvé par le halfelin. Séance 02 : en route vers Phandalin ; entend les clients de la taverne chuchoter à leur sujet. Séance 03 : reconnaît l'emblème de la guilde ; son poignard finit au plafond pendant l'épreuve ; réclame du chocolat. Séance 04 : sent la magie du navire, assiste Corvis à la navigation ; reconnu et ligoté, se blesse avec son poignard. Séance 05 : révèle qu'il respire sous l'eau ; cauchemar sur son passé ; quart déguisé en capitaine. Séance 06 : cherche du chocolat ; trouve que la langue locale ressemble à du beatbox ; partage sa chambre avec Kael."}, {"t": "Obélik", "u": "personnages/obelik.html", "k": "🛡️ Personnages", "a": "Obelik", "x": "Présentation Goliath barbare, évadé de la Prison de Waterdeep avec Morrÿs et Kael . Optimiste. Ancien fermier. Capacités notables Équipement notable Le Journal de la naine , dans une petite bourse accrochée à son pagne (depuis la Séance 06 ). Historique Séance 01 : se réveille en cellule avec Kael et Morrÿs, s'évade. Séance 02 : voit la fumée au-dessus de Phandalin et conclut qu'« ils ont déjà allumé le barbecue ». Séance 03 : reconnaît l'emblème de la guilde ; touche puis immobilise Lyra, récupère le poignard de Morrÿs au plafond. Séance 04 : ancien fermier ; se fait passer pour « Hervé » ; tranche la corde, blessé par un carreau, repêche et gifle Corvis. Séance 05 : cauchemar ; mal de mer ; prend des tortues pour un dragon ; révèle au domestique qu'ils viennent de la guilde. Séance 06 : garde le journal de la naine (bourse accrochée au pagne) ; repère le panneau des guides ; entend les rumeurs sur les processions et le Zhentarim."}, {"t": "Alan", "u": "pnj/alan.html", "k": "👤 PNJ", "a": "", "x": "Tavernier de Waterdeep , évadé de la Prison de Waterdeep avec le groupe. Il a donné son nom à la campagne. Travaille désormais aux cuisines du QG des Faiseurs de Veuves . Relations Kael , Morrÿs , Obélik : compagnons d'évasion Neverember : Alan ressemble à son fils, on les confond souvent à Waterdeep Ce qu'on sait Gérant (pas propriétaire) d'une taverne à Waterdeep, qu'il voudrait racheter un jour. Emprisonné pour « propagande » : il posait des affiches publicitaires pour sa taverne. Très attaché aux chopes. Ne connaît pas le chocolat ; le groupe a promis de lui rapporter des épices de Chult. Mystères ❓ Le halfelin a cru le reconnaître à la sortie de la prison ; Alan dit ne pas le connaître. Lien avec sa ressemblance au fils de Neverember ? Historique Séance 01 : rencontre le groupe dans la salle des gardes, s'évade avec lui ; le halfelin semble le reconnaître, il nie le connaître. Séance 02 : fait route vers Phandalin ; raconte sa taverne, son arrestation et sa ressemblance avec le fils de Neverember. Séance 03 : prend une place dans les cuisines du QG, cuisine un chevreuil en sauce. Séance 04 : assiste au départ ; son portrait figure sur l'avis de recherche de la garde."}, {"t": "Arlan", "u": "pnj/arlan.html", "k": "👤 PNJ", "a": "", "x": "Frère de Corvis Quillfore , ancien pêcheur de Leilon ; ils possèdent ensemble une compagnie de transport maritime. Jamais rencontré. Relations Corvis Quillfore : frère Ce qu'on sait A cuisiné le ragoût de chevreuil (la recette d' Alan ) trouvé à bord de L'Effleureuse . Était parti avec un autre navire quand l'Effleureuse a dû emmener le groupe. Historique Séance 04 : évoqué : « le frère » de Corvis, qui a cuisiné le ragoût. Séance 05 : on apprend son nom : parti avec un autre navire, co-fondateur de la compagnie de transport."}, {"t": "Corrin Thinspike", "u": "pnj/corrin-thinspike.html", "k": "👤 PNJ", "a": "Le halfelin mystérieux Corrin", "x": "Mystérieux halfelin rencontré à la sortie de la Prison de Waterdeep . Il a abattu d'une flèche la créature invisible qui attaquait Virgile , l'a soigné, a conseillé au groupe d'aller à Phandalin , puis est reparti explorer la prison en marchant sur les murs et au plafond. Il a ensuite prévenu Yarno El Raïb de l'arrivée du groupe et l'a recommandé. Relations Alan : a cru le reconnaître Yarno El Raïb , Faiseurs de Veuves : en contact avec eux Ce qu'on sait Halfelin d'une soixantaine d'années, archer redoutable. Capable de marcher sur les murs et au plafond. Mystères ❓ Qui est-il, que cherche-t-il dans la prison ? Historique Séance 01 : halfelin inconnu : tue la créature invisible d'une flèche, soigne le capitaine, semble reconnaître Alan, conseille Phandalin et repart au plafond de la prison. Séance 02 : évoqué — reparti vers la prison après avoir soigné Virgile. Séance 03 : on apprend son nom par Yarno : il a prévenu la guilde et recommandé le groupe."}, {"t": "Corvis Quillfore", "u": "pnj/corvis-quillfore.html", "k": "👤 PNJ", "a": "Corvis", "x": "Capitaine de L'Effleureuse , a conduit le groupe de Leilon à Port Nyanzaru ; il y cherche un équipage avant de repartir vers les îles Solaires. Ancien pêcheur, il possède avec son frère une compagnie de transport. Relations Arlan : son frère Faiseurs de Veuves : leur rend service Ce qu'on sait Prévenu la veille du départ, sans équipage : le groupe fait les manœuvres. Déjà contrôlé plusieurs fois par la garde de Waterdeep. Possède un petit objet bleu qui active le pouvoir du navire (pas utilisable à volonté). Ne connaît pas le chocolat. Ne connaît pas Chult, préfère les trajets côtiers. Historique Séance 04 : accueille le groupe à Leilon, trompe la garde, active le pouvoir du navire ; passe par-dessus bord, ranimé par une gifle d'Obélik. Séance 05 : raconte Leilon et son frère ; dépose le groupe à Port Nyanzaru et part chercher un équipage."}, {"t": "Jeanne Von Brocht", "u": "pnj/jeanne-von-brocht.html", "k": "👤 PNJ", "a": "Jane Von Brote Jeanne von Brocht", "x": "Lord actuelle de Waterdeep , a succédé à Neverember . Jamais rencontrée. Ce qu'on sait Arrête les gens à tour de bras. Les Faiseurs de Veuves veulent réunir des preuves pour la faire tomber. Surnommée « l'autre connasse » par le groupe. Historique Séance 02 : évoquée (successeure de Neverember). Séance 03 : « l'autre connasse » : elle arrête à tour de bras, la guilde veut réunir des preuves pour la faire tomber."}, {"t": "Kaya", "u": "pnj/kaya.html", "k": "👤 PNJ", "a": "", "x": "Tient la Maison de repos de Kaya à Port Nyanzaru . Tenancière austère, très attachée à son commerce et à sa réputation (« un sou est un sou »), sincère selon Kael. Attendait le groupe. N'est jamais sortie de la ville. Ce qu'on sait Conseils : à Chult, on est des proies ; peu d'expéditions reviennent, aucune n'a réussi à cartographier l'île ; suivre une rivière (Soshenstar) pour ne pas se perdre, en pirogue ou canoë ; prendre un guide ( Guilde des guides ) : tous ceux qui sont revenus en avaient un. Zombies (depuis toujours ; origine et chef inconnus, une faction liée) et dinosaures (n'attaquent que s'ils ont faim ou se sentent menacés) ; au nord, le Fort Beluarian et sa milice. Vend les affaires des clients qui ne reviennent pas sous 14 jours. Historique Séance 06 : accueille le groupe et le conseille."}, {"t": "La Paire", "u": "pnj/la-paire.html", "k": "👤 PNJ", "a": "Iolka Vesper Nera Vesper Iolka et Nera Vesper Iolka Nera", "x": "Iolka et Nera Vesper, deux sœurs surnommées « la Paire » : vigies des Faiseurs de Veuves à Chult , contacts du groupe sur place. Elles logent chez Wakanga O'Tamu quand elles ne sont pas en vadrouille. Relations Wakanga O'Tamu : les héberge Yarno El Raïb : les a désignées comme contacts Ce qu'on sait Le groupe a une vieille photo d'elles. Parties sur une mission inconnue de Wakanga ; sans nouvelles depuis une vingtaine de jours à l'arrivée du groupe. Mystères ❓ Où sont-elles ? Historique Séance 03 : évoquées par Yarno, qui donne leur photo. Séance 05 : Wakanga n'a plus de nouvelles depuis une vingtaine de jours (autre mission)."}, {"t": "La créature invisible", "u": "pnj/la-creature-invisible.html", "k": "👤 PNJ", "a": "Créature invisible", "x": "Créature invisible armée d'une épée, qui a abattu deux fois Virgile à la sortie de la Prison de Waterdeep . Visible seulement un instant avant de frapper. Tuée d'une flèche par Corrin Thinspike . Ce qu'on sait Selon le halfelin, sa présence à cet endroit n'avait rien de normal : « on n'envoie pas une telle chose ici sans raison ». Mystères ❓ Qui l'a envoyée, et pour qui ? Historique Séance 01 : attaque le capitaine, tente de tuer Morrÿs, abattue par le halfelin."}, {"t": "Le capitaine de la BITE", "u": "pnj/le-capitaine-de-la-bite.html", "k": "👤 PNJ", "a": "Capitaine de la BITE", "x": "Capitaine du navire de la Brigade d'Intervention Technique et Expéditive qui a contrôlé L'Effleureuse . Nom inconnu. Relations Rico, Muso : soldats sous ses ordres Ce qu'on sait Ancien marin dans l'import-export ; a perdu sa licence, a pris ce poste « parce qu'il faut bien vivre ». Avait un avis de recherche avec les portraits de Kael, Obélik, Morrÿs et Alan. Historique Séance 04 : contrôle l'Effleureuse, reconnaît Morrÿs, jeté à l'eau par Kael."}, {"t": "Le domestique de Wakanga", "u": "pnj/le-domestique-de-wakanga.html", "k": "👤 PNJ", "a": "Serviteur de Wakanga Domestique de Wakanga", "x": "Domestique de Wakanga O'Tamu , un éventail plié à la main. Nom inconnu. Relations Wakanga O'Tamu : son maître Historique Séance 05 : aborde le groupe sur le quai (« les voyageurs envoyés par la guilde ? ») et le conduit à la villa. Séance 06 : explique les tarifs des guides et remet leurs prospectus."}, {"t": "Lyra Sunstrike", "u": "pnj/lyra-sunstrike.html", "k": "👤 PNJ", "a": "Lyra Lyra Sunstricke L'elfe de Phandalin", "x": "Elfe des Faiseurs de Veuves qui attendait le groupe aux abords de Phandalin , puis lui a fait passer l'épreuve de combat. Relations Faiseurs de Veuves : membre Ce qu'on sait Attendait le groupe devant la villa de la guilde depuis 4 ou 5 jours. Moine : en voyage, cape sombre et masque pâle lié à sa discipline monacale. Se bat à mains nues : un coup de paume vide l'énergie de sa cible ; un autre geste semble en rendre une partie. Mystères ❓ Comment savait-elle que le groupe arrivait ? Historique Séance 02 : accueille le groupe devant la villa à l'étoile à huit branches (nom pas encore connu). Séance 03 : on apprend son nom ; épreuve de combat contre le groupe ; soigne Virgile. Séance 04 : accompagne le groupe jusqu'à Leilon, en tenue monacale et masquée."}, {"t": "Neverember", "u": "pnj/neverember.html", "k": "👤 PNJ", "a": "Neveramber", "x": "Lord de Waterdeep avant Jeanne Von Brocht . Jamais rencontré. Relations Alan : ressemble à son fils Ce qu'on sait A un fils avec qui Alan est souvent confondu. Historique Séance 02 : évoqué par Alan."}, {"t": "River Mist et Flask of Wine", "u": "pnj/river-mist-et-flask-of-wine.html", "k": "👤 PNJ", "a": "River Mist Flask of Wine River Mist & Flask of Wine Malar's Throat", "x": "Signataires de l'annonce non officielle « Malar's Throat » (du nom d'un quartier de Port Nyanzaru ) glissée sur le panneau des guides de la Maison de repos de Kaya : « On trouvera là où vous voulez aller. Et on le saura discrètement. », avec en accroche : « Pas de prince, pas de registre, pas de questions. » Jamais rencontrés. Ce qu'on sait Selon Salida (voir Guilde des guides ), ils doivent de l'argent au Zhentarim . Pour Kael, leur annonce ressemble à du racolage. Mystères ❓ Un ou deux personnages ? Guides ou autre chose ? Historique Séance 06 : leur annonce sur le panneau ; cités dans le prospectus de Salida."}, {"t": "Syndra", "u": "pnj/syndra.html", "k": "👤 PNJ", "a": "", "x": "Très vieille elfe, amie de longue date de Wakanga O'Tamu . Morte autrefois dans une embuscade puis ressuscitée, elle dépérit sous l'effet du mal qui frappe tous les ressuscités. Relations Wakanga O'Tamu : amie de longue date, confiance « qui dépasse la simple amitié » Ce qu'on sait Porte une capuche et un masque de dentelle. A enquêté : la source du mal serait dans la jungle de Chult , sans doute loin au sud. Soupçonne un artefact magique plutôt qu'une malédiction divine. Historique Séance 05 : raconte sa mort et son mal ; le groupe accepte de l'aider."}, {"t": "Virgile", "u": "pnj/virgile.html", "k": "👤 PNJ", "a": "Le capitaine Capitaine de la prison", "x": "Capitaine de la Prison de Waterdeep . Transpercé par une créature invisible à la sortie de la prison, soigné par le halfelin , il accompagne les évadés jusqu'à Phandalin , puis repart à Waterdeep pour ne pas être considéré comme déserteur. Relations Kael , Morrÿs , Obélik , Alan : les a laissés partir, voyage avec eux Faiseurs de Veuves : compte sur eux pour le soigner Ce qu'on sait Affecté à la garde de la prison depuis l'année dernière. A sondé la faille de la prison en y jetant une chope (vidée avant) : trou très profond (« 10 secondes »). Sa version officielle : les prisonniers se sont joués de lui et se sont échappés. Il préfère passer pour incompétent que pour traître. Mystères ❓ Comment connaît-il les Faiseurs de Veuves ? Historique Séance 01 : capitaine (nom encore inconnu) : combat les kobolds avec le groupe, le laisse partir, abattu par la créature invisible puis soigné par le halfelin. Séance 02 : donne son nom, guide le groupe vers Phandalin, le couvre à la taverne et présente les Faiseurs de Veuves. Séance 03 : soigné au QG, repart à Waterdeep pour ne pas être déserteur. Séance 04 : assiste au départ du groupe."}, {"t": "Wakanga O'Tamu", "u": "pnj/wakanga-o-tamu.html", "k": "👤 PNJ", "a": "Wakanga Wakanga Otamu", "x": "Mage, l'un des sept Princes marchands de Port Nyanzaru . Commanditaire de la mission du Gardien Bouclier . Responsable des objets magiques et de l'information. Veut aussi sauver son amie Syndra . Relations Faiseurs de Veuves : a fait appel à eux La Paire : les héberge Syndra : amie de longue date Ce qu'on sait Cherche un Gardien Bouclier et son amulette de contrôle ; paie toute information, prime importante pour le Gardien ou l'amulette. Tient à sa réputation : exige discrétion et efficacité. Voudrait étudier le Soulmonger , mais accepte qu'il soit détruit s'il le faut. Historique Séance 03 : évoqué : commanditaire de la mission. Séance 05 : accueille le groupe, présente Syndra, évoque le Soulmonger, remet une carte de Chult et paie l'auberge."}, {"t": "Yarno El Raïb", "u": "pnj/yarno-el-raib.html", "k": "👤 PNJ", "a": "Yarno", "x": "Membre des Faiseurs de Veuves au QG de Phandalin . Prévenu par Corrin Thinspike , il a confié au groupe la mission du Gardien Bouclier à Chult après une épreuve. Relations Corrin Thinspike : l'a prévenu de l'arrivée du groupe Lyra Sunstrike : lui fait passer les épreuves Destos : l'envoie avec le groupe Ce qu'on sait A été envoyé en prison, il y a plusieurs années, par l'un des quatre fondateurs de la guilde. Veut faire tomber Jeanne Von Brocht . Mystères ❓ Quel fondateur l'a fait emprisonner, et pourquoi ? Historique Séance 03 : accueille le groupe, lui fait passer l'épreuve et lui confie la mission de Chult."}, {"t": "Chult", "u": "lieux/chult.html", "k": "🏰 Lieux", "a": "", "x": "Terre tropicale couverte d'une jungle dangereuse, peuplée de créatures hostiles, venimeuses ou empoisonnées, de dinosaures et de zombies. Peu d'explorateurs en reviennent ; personne ne l'a entièrement cartographiée. Port Nyanzaru en est la seule cité. À 21 jours de mer de la Côte des Épées (40 si le temps est mauvais). Points d'intérêt Fort Beluarian , au nord : défense contre les zombies. Une immense montagne au centre de l'île. La rivière Soshenstar, qui part de Port Nyanzaru vers le sud (d'autres rivières sur la carte). De vastes régions inexplorées (carte de Wakanga : un hexagone ≈ 15 km). Port Nyanzaru Habitants et PNJ La Paire Historique Séance 03 : destination de la mission, décrite par Yarno. Séance 05 : arrivée par le nord ; carte remise par Wakanga. Séance 06 : Kaya décrit les dangers de l'île."}, {"t": "Fort Beluarian", "u": "lieux/fort-beluarian.html", "k": "🏰 Lieux", "a": "Fort Berulian", "x": "Fort au nord de Chult , au-dessus de Port Nyanzaru sur la carte de l'île. Une milice armée y maintient l'ordre et tient les zombies à l'écart (d'après Kaya ). Historique Séance 06 : évoqué par Kaya."}, {"t": "Leilon", "u": "lieux/leilon.html", "k": "🏰 Lieux", "a": "", "x": "Petite ville portuaire à deux heures de marche de Phandalin , d'où part L'Effleureuse . Ancien port de pêche, elle a grandi quand les Faiseurs de Veuves y ont rallumé la forge magique : voyageurs, marchands de matières premières et d'objets magiques, aventuriers. Points d'intérêt Le port La forge magique, rallumée par les Faiseurs de Veuves Habitants et PNJ Corvis Quillfore Arlan Historique Séance 04 : embarquement sur l'Effleureuse. Séance 05 : Corvis raconte l'histoire de la ville."}, {"t": "Maison de repos de Kaya", "u": "lieux/maison-de-repos-de-kaya.html", "k": "🏰 Lieux", "a": "Auberge de Kaya", "x": "Auberge près du bazar rouge de Port Nyanzaru , recommandée par Wakanga O'Tamu qui en paie les frais. Tenue par Kaya , plus à l'est, près d'un autre marché. Points d'intérêt Salle avec bar à gauche (boissons locales), 4 à 5 tables ; long couloir vers les chambres. Chambres 40 et 42 (celles du groupe), au fond : deux lits simples, table de nuit commune, armoire, fenêtre sur cour intérieure. Repas du soir compris ; brunch à 1 pa par personne. Clientèle de classe moyenne ; lieu propre et confortable. Règles : ne voler ni déranger personne ; rendre les clés en partant en expédition ; affaires vendues par Kaya si on ne revient pas sous 14 jours. Panneau d'annonces à l'entrée (guides, voir Guilde des guides ). Habitants et PNJ Kaya Historique Séance 05 : recommandée par Wakanga. Séance 06 : le groupe s'y installe (chambres 40 et 42) ; rumeurs au petit-déjeuner."}, {"t": "Phandalin", "u": "lieux/phandalin.html", "k": "🏰 Lieux", "a": "Phandaline", "x": "Ville à deux jours de marche de Waterdeep , où les Faiseurs de Veuves ont leur QG. Points d'intérêt QG des Faiseurs de Veuves Habitants et PNJ Lyra Sunstrike Historique Séance 02 : arrivée du groupe ; une colonne de fumée s'élève au-dessus de la ville. Séance 03 : séjour au QG de la guilde, départ à l'aube. Séance 04 : départ du groupe avant l'aube."}, {"t": "Port Nyanzaru", "u": "lieux/port-nyanzaru.html", "k": "🏰 Lieux", "a": "Nyanzaru", "x": "Seule cité de Chult , gouvernée par les sept Princes marchands . Dernier vrai refuge avant la jungle. Commerce d'épices, fruits, ivoire… Points d'intérêt Port au nord : digue formant une baie, chaîne de fermeture, phare (à droite), fort à canons (à gauche). Grand bazar à trois branches (en Y/T), ouvert tous les jours du petit matin au soir. Un palais doré sur une colline, qui domine la ville, les quartiers marchands et le port. Le grand colisée (courses de dinosaures ?). Malar's Throat : un quartier, sans doute mal famé (impression du groupe). Le Lézard tonnant , une auberge sur la route du bazar rouge. Bureau d'information du port (recommandations sur les guides). Bazar (est) et bazar rouge, avec la Maison de repos de Kaya ; marché de l'est (viande de dinosaure, fruits, légumes, vêtements). Temple de Gond . Quartier marchand (ouest) : Villa de Wakanga O'Tamu , fresques de dinosaures. Courses de dinosaures (hadrosaures, dimétrodons, jeunes tricératops et tyrannosaures…) ; paris ouverts. Une course a lieu deux jours après l'arrivée du groupe. Enceinte de la « course contre la mort », hors de la ville. Ambiance Ville à deux vitesses : quartiers silencieux et en deuil (fidèles en blanc et noir), et des gens en vêtements très colorés qui parlent fort un créole local fait de claquements de gorge et de dents (on dirait du beatbox). Les Chultais s'habillent de façon ostentatoire, même les plus pauvres : drapés très colorés. Ville fortifiée, garde efficace. La procession funèbre part à l'aube et traverse la ville au lever du soleil. Coutumes et justice Esclavage interdit, crimes sévèrement punis. Un affront se règle à l'amiable ou devant les autorités ; ordres d'assassinat légaux, sous conditions et contre paiement. Course contre la mort : le condamné doit atteindre la sortie, poursuivi par des dinosaures choisis selon sa faute ; s'il survit, sa dette est effacée. La mort compte beaucoup : processions d'autant plus fastueuses que le défunt était riche ou puissant. Habitants et PNJ Wakanga O'Tamu La Paire Syndra Kaya Historique Séance 03 : évoquée par Yarno. Séance 05 : arrivée au milieu d'une procession funèbre ; rencontre de Wakanga. Séance 06 : traversée de la ville, marchés, temple de Gond ; rumeurs sur les morts."}, {"t": "Prison de Waterdeep", "u": "lieux/prison-de-waterdeep.html", "k": "🏰 Lieux", "a": "La prison Prison", "x": "Prison creusée dans une montagne, où Kael , Morrÿs et Obélik se sont réveillés, et d'où ils se sont évadés avec Alan . Points d'intérêt Une fosse commune remplie de cadavres. Un escalier magique de 50 à 100 marches menant au hall : il se change en toboggan et déclenche une alarme (un code, trouvé sur un garde, permet sans doute de le franchir). Une immense faille dont on ne voit pas le fond : Virgile y a jeté une chope, trou très profond (« 10 secondes »). Habitants et PNJ Virgile : capitaine de la garde Corrin Thinspike : reparti l'explorer Historique Séance 01 : évasion au milieu d'une invasion de kobolds : faille, fosse commune, escalier-toboggan, combat dans le hall. Séance 02 : Virgile raconte l'expérience de la chope."}, {"t": "QG des Faiseurs de Veuves", "u": "lieux/qg-des-faiseurs-de-veuves.html", "k": "🏰 Lieux", "a": "Villa des Faiseurs de Veuves", "x": "Quartier général des Faiseurs de Veuves à Phandalin : une vaste demeure hors de la ville, marquée près de la porte d'une étoile à huit branches semblable à un soleil. Points d'intérêt Étoile à huit branches, symbole de la guilde. Patio baigné de lumière. Sous-sol : salle d'armes et terrain d'entraînement. Étage : chambres avec terrasse plein sud ; au loin, la montagne de la Prison de Waterdeep . Jardin : quatre statues des fondateurs de la guilde. Cuisines (où travaille Alan ) et Salon Bleu. Habitants et PNJ Lyra Sunstrike Yarno El Raïb Alan Historique Séance 02 : le groupe y est attendu. Séance 03 : épreuve au sous-sol, chambres à l'étage, dîner au Salon Bleu."}, {"t": "Temple de Gond", "u": "lieux/temple-de-gond.html", "k": "🏰 Lieux", "a": "Gond", "x": "Petit temple de Gond, dans le quartier marchand de Port Nyanzaru (une simple pancarte). Gond est le dieu des portes, au sens propre (proche des serruriers) comme au sens philosophique (les opportunités, les portes qui s'ouvrent ou se ferment) ; très lié au destin. Vénéré par les artisans et les travailleurs manuels ; ses temples portent un petit symbole de forge (ce que sait Destos). Historique Séance 06 : le groupe passe devant."}, {"t": "Villa de Wakanga O'Tamu", "u": "lieux/villa-de-wakanga-o-tamu.html", "k": "🏰 Lieux", "a": "Villa de Wakanga", "x": "Demeure luxueuse de Wakanga O'Tamu dans le quartier marchand (ouest) de Port Nyanzaru , aux murs couverts de fresques de dinosaures. Refuge sûr pour les aventuriers qui travaillent avec lui. Points d'intérêt Antichambre, petit salon Habitants et PNJ Wakanga O'Tamu Syndra La Paire (quand elles ne sont pas en mission) Historique Séance 05 : Wakanga présente Syndra et confie la mission du mal des ressuscités. Séance 06 : retour : prospectus des guides."}, {"t": "Waterdeep", "u": "lieux/waterdeep.html", "k": "🏰 Lieux", "a": "", "x": "Grande cité, dirigée par Jeanne Von Brocht (auparavant Neverember ). Le groupe s'est évadé de sa prison. Points d'intérêt Prison de Waterdeep La taverne gérée par Alan Habitants et PNJ Alan Virgile Historique Séance 01 : le groupe s'évade de la prison de la cité. Séance 02 : le groupe la quitte pour Phandalin . Séance 03 : impossible d'y retourner ; Virgile y repart."}, {"t": "Brigade d'Intervention Technique et Expéditive", "u": "factions/brigade-d-intervention-technique-et-expeditive.html", "k": "⚜️ Factions", "a": "BITE La BITE", "x": "Le fleuron de la garde de Waterdeep , qui contrôle les navires en mer. Membres connus Le capitaine de la BITE : capitaine d'un navire Rico, Muso : soldats Ce qu'on sait Recherche Kael, Obélik, Morrÿs et Alan (avis de recherche avec portraits). Historique Séance 04 : contrôle et poursuite de l'Effleureuse ; le navire s'échoue sur un banc de sable."}, {"t": "Enclave d'Émeraude", "u": "factions/enclave-d-emeraude.html", "k": "⚜️ Factions", "a": "Enclave émeraude Emerald Enclave", "x": "Guilde de druides qui cherche à maintenir l'équilibre et l'ordre naturel des choses, ce qui n'est pas forcément le bien (ce que sait Destos). Ce qui n'est pas naturel doit disparaître, les morts-vivants en premier ; quitte à être radical : si un village a brûlé une forêt, il faudrait brûler le village. Membres connus Qawasha : druide, guide (voir Guilde des guides ) Historique Séance 06 : rumeur entendue par Destos ; Qawasha s'en réclame dans son prospectus."}, {"t": "Faiseurs de Veuves", "u": "factions/faiseurs-de-veuves.html", "k": "⚜️ Factions", "a": "FdV Faiseur de veuve Faiseurs de veuves la guilde", "x": "Guilde née à Phandalin il y a une trentaine d'années, qui œuvre pour le bien du royaume jusque sur la Côte des Épées. Symbole : une étoile à huit branches semblable à un soleil. Réputation établie depuis une vingtaine d'années ; son nom vient de sa toute première mission, où elle n'a pas réussi à sauver tous les otages. Membres connus Lyra Sunstrike : elfe, a accueilli le groupe Yarno El Raïb : a confié la mission de Chult La Paire : vigies à Chult Quatre fondateurs (statues au jardin du QG), dont l'un a fait emprisonner Yarno Ce qu'on sait Peut soigner Virgile (selon lui). Mission : retrouver les objets magiques dangereux, les neutraliser, les détruire si nécessaire. Ni collectionneurs, ni pillards. Cherche à réunir des preuves pour faire tomber Jeanne Von Brocht . Ne veut pas apparaître à Chult : le groupe y agit en son nom propre. Historique Séance 02 : présentée par Virgile ; une de ses membres attend le groupe aux portes de Phandalin. Séance 03 : le groupe entre au QG ; Yarno explique la mission de la guilde et envoie le groupe à Chult. Séance 04 : Lyra accompagne le groupe à Leilon ; la guilde reste discrète sur Chult. Séance 05 : Obélik confirme au domestique de Wakanga qu'ils viennent de la guilde ; on apprend que la guilde a rallumé la forge magique de Leilon."}, {"t": "Guilde des guides", "u": "factions/guilde-des-guides.html", "k": "⚜️ Factions", "a": "Guides Guides de Port Nyanzaru Guilde de guides", "x": "Guilde des guides de la jungle de Chult , contrôlée par Jobal, l'un des Princes marchands . Métier très réglementé : tarif unique, 5 po par jour, 30 jours payés avant le départ (soit 150 po). Selon Kaya , tous ceux qui sont revenus de la jungle avaient un guide. Prospectus remis par Le domestique de Wakanga ( Séance 06 ), qui conseille aussi le bureau d'information du port. Panneau de la Maison de repos de Kaya : « En quête d'aventure ? Garantissez votre retour : sollicitez un guide. » Six annonces officielles et une septième ajoutée en douce (Malar's Throat). Membres connus Azaka Stormfang : née dans la jungle, en connaît les dangers. Renonce à son tarif si on l'aide dans une quête personnelle : récupérer un masque de bois que lui ont volé les ptérafolks nichant au sommet de Firefinger. Eku : veut débarrasser la jungle du mal, reprendre ruines et temples pour que les esprits de la nature y reviennent. Met en garde contre des imposteurs qui promettent de l'or et mènent à la mort. Une petite part de son tarif va au prince Jobal (frais de la guilde), le reste à la charité. Faroul & Gondolo : deux guides pour le prix d'un, avec leur propre tricératops ; promettent trésors et magie. Tarif réduit contre des parts égales du trésor trouvé. Hew Hackinstone : nain, dit avoir gravi toutes les montagnes de Chult, n'oublie rien, n'a peur de rien ; un dragon rouge lui a arraché un bras. Musharib : nain. Veut reprendre Hrakhamar, la forge ancestrale de son clan, abandonnée après une éruption et occupée depuis par des firenewts ; au minimum, récupérer une relique, le Gantelet de Moradin. Renonce à son tarif contre la promesse d'aide. Qawasha & Kupalué : Qawasha, druide de l' Enclave d'Émeraude , veut débarrasser Chult des morts-vivants ; son compagnon vegepygmy Kupalué connaît la faune et la flore. Tarif négociable si on aide à détruire les morts-vivants ; évoquent la bénédiction des esprits chwinga. Absents du panneau. Salida : dit connaître des sentiers secrets absents des cartes, et dénigre les autres : les expéditions d'Azaka et d'Eku ne sont jamais revenues, Faroul et Gondolo sont des charlatans, Hew souffre de la fièvre de la brume bleue, Musharib est un nain albinos pas fiable, et « River Mist » et « Flask of Wine » doivent de l'argent au Zhentarim . ~~ Malar's Throat : sur le panneau, sans prospectus.~~ Corrigé d'après la transcription : ce n'est pas un guide. Malar's Throat est un quartier de Port Nyanzaru ; c'est le titre de la 7ᵉ annonce, non officielle, d'une autre écriture et glissée de force entre les autres : « Pas de prince, pas de registre, pas de questions. On trouvera là où vous voulez aller. Et on le saura discrètement. », signée River Mist et Flask of Wine . Kael y voit du racolage. Ce qu'on sait Les prospectus sont en anglais (langue de la table) ; noms reproduits tels quels. Les cartes du panneau portent aussi de courtes accroches (transcription et notes de Kael) : Azaka, « la jungle me connaît par mon odeur, pas par mon nom ; je ne prends pas de l'or, mais de la dette » (le groupe s'en méfie) ; Eku, « quand vous ne voyez plus ce qui arrive, c'est le moment de me trouver » ; Faroul & Gondolo, deux guides pour le prix d'un et un tricératops, partage égal ; Hew Hackinstone, la loyauté des nains ; Musharib, « la forge n'est pas perdue, elle est en attente » ; Salida, « au sud, toujours au sud… rapide, expérimenté, je déteste attendre ». Dangers cités dans les prospectus : morts-vivants, firenewts, ptérafolks (Firefinger = « le doigt de feu »). Les sceaux rouges sur certaines cartes ne signifient rien de particulier. D'après l'intuition de Kael, les plus compétents sont sans doute aussi les plus chers. Plusieurs membres du groupe se méfient de Salida, qui dénigre les autres au lieu de se vendre. Mystères ❓ Qui dit vrai parmi les accusations de Salida ? ❓ Que valent River Mist et Flask of Wine ? Historique Séance 06 : panneau à l'auberge de Kaya ; tarifs et prospectus remis par le domestique de Wakanga."}, {"t": "Princes marchands", "u": "factions/princes-marchands.html", "k": "⚜️ Factions", "a": "Prince marchand Princes et princesses marchands", "x": "Les sept princes et princesses marchands qui gouvernent Port Nyanzaru . Pas une lignée royale : ce sont les personnes les plus riches et influentes de la cité, qui se partagent ses domaines. Membres connus Wakanga O'Tamu : mage — objets magiques et information Ekene-Afa : armes, boucliers, matériel de voyage Ifan Talro'a : animaux, dressage (courses, exécutions) Jessamine : plantes, ordres d'assassinat Jobal : guides et espions — contrôle la Guilde des guides Kwayothé : nourriture, boissons, parfums, répulsifs Zhanthi : gemmes, vêtements, armures Ce qu'on sait Chacun a une voix au gouvernement de la cité. En cas de conflit, mieux vaut s'adresser à eux que se faire justice soi-même. Historique Séance 03 : évoqués par Yarno au dîner. Séance 05 : Wakanga détaille les sept princes et leurs domaines. Séance 06 : on apprend que Jobal contrôle la guilde des guides."}, {"t": "Zhentarim", "u": "factions/zhentarim.html", "k": "⚜️ Factions", "a": "Réseau noir Zntarin", "x": "Le « réseau noir », une guilde de mercenaires qui cherche à gagner toujours plus de pouvoir. Ils font le mal comme le bien, tant que ça paie ; ils agissent discrètement, mais on les dit derrière la plupart des combines et complots des différentes régions (ce que sait Obélik). Ce qu'on sait Selon Salida, River Mist et Flask of Wine lui doivent de l'argent. Historique Séance 06 : rumeur entendue par Obélik ; cité dans le prospectus de Salida."}, {"t": "Gardien Bouclier", "u": "objets/gardien-bouclier.html", "k": "💎 Objets", "a": "Gardien bouclier Amulette du Gardien Bouclier Construct Le construct", "x": "Un Gardien Bouclier (appelé aussi « le construct »), contrôlé par une amulette. Wakanga O'Tamu cherche l'un et l'autre. D'après le Journal de la naine , il se trouverait à l'intérieur des terres de Chult . Historique Séance 03 : objet de la mission confiée par Yarno. Séance 05 : le journal d'une naine le situe à l'intérieur des terres. Séance 06 : on l'appelle aussi « le construct »."}, {"t": "Journal de la naine", "u": "objets/journal-de-la-naine.html", "k": "💎 Objets", "a": "Journal d'une naine Le journal", "x": "Journal d'une naine, remis par Wakanga O'Tamu : il situe le Gardien Bouclier à l'intérieur des terres de Chult , peut-être en suivant la rivière. Historique Séance 05 : Wakanga en tire la première piste du Gardien Bouclier. Séance 06 : Obélik le garde dans une petite bourse accrochée à son pagne."}, {"t": "L'Effleureuse", "u": "objets/l-effleureuse.html", "k": "💎 Objets", "a": "Effleureuse", "x": "Trois-mâts fin comme un oiseau, commandé par Corvis Quillfore . Imprégné de magie de la proue à la poupe. Fait pour un équipage réduit. Activé par un petit objet bleu, il peut bondir et surfer sur les vagues (pouvoir non utilisable à volonté). Historique Séance 04 : le groupe embarque ; saut par-dessus les hauts-fonds pour semer la garde. Séance 05 : vingt jours de traversée jusqu'à Port Nyanzaru."}, {"t": "Soulmonger", "u": "objets/soulmonger.html", "k": "💎 Objets", "a": "", "x": "Rumeur rapportée par Wakanga O'Tamu : un objet quelque part à Chult qui capturerait les âmes des défunts. Existence non confirmée. Lien supposé avec Le mal des ressuscités . Historique Séance 05 : rumeur rapportée par Wakanga."}];

(function () {
  const q = document.getElementById("q"), out = document.getElementById("results");
  const fold = s => s.normalize("NFD").replace(/[̀-ͯ]/g, "").toLowerCase();
  const idx = window.SEARCH_INDEX.map(e => ({...e, ft: fold(e.t + " " + e.a), fx: fold(e.x)}));
  function esc(s) { return s.replace(/[&<>"]/g, c => ({"&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;"}[c])); }
  function run() {
    const terms = fold(q.value).split(/\s+/).filter(Boolean);
    if (!terms.length) { out.innerHTML = ""; return; }
    const hits = [];
    for (const e of idx) {
      let score = 0, ok = true;
      for (const t of terms) {
        if (e.ft.includes(t)) score += 10;
        else if (e.fx.includes(t)) score += 1;
        else { ok = false; break; }
      }
      if (ok) hits.push([score, e]);
    }
    hits.sort((a, b) => b[0] - a[0]);
    out.innerHTML = hits.slice(0, 15).map(([_, e]) => {
      let snip = "";
      const i = e.fx.indexOf(terms[0]);
      if (i >= 0) snip = "…" + esc(e.x.slice(Math.max(0, i - 40), i + 80)) + "…";
      return `<li><a href="${window.SITE_PREFIX}${e.u}"><b>${esc(e.t)}</b> <small>${esc(e.k)}</small><span>${snip}</span></a></li>`;
    }).join("") || "<li class='none'>Aucun résultat</li>";
  }
  q.addEventListener("input", run);
  q.addEventListener("keydown", ev => {
    if (ev.key === "Enter") { const a = out.querySelector("a"); if (a) location.href = a.href; }
    if (ev.key === "Escape") { q.value = ""; run(); q.blur(); }
  });
  document.addEventListener("keydown", ev => {
    if (ev.key === "/" && document.activeElement !== q) { ev.preventDefault(); q.focus(); }
  });
})();
